do $test$
declare subject uuid:=gen_random_uuid(); actor uuid:='00000000-0000-4000-8000-00000000c0c0'; plan jsonb; path text; booking uuid:=gen_random_uuid(); candidature uuid:=gen_random_uuid(); casting uuid:=gen_random_uuid(); role_id uuid:=gen_random_uuid();
begin begin
 assert not has_table_privilege('anon','public.rgpd_fichiers_a_effacer','SELECT'),'File visible anon';
 assert not has_table_privilege('authenticated','public.rgpd_fichiers_a_effacer','SELECT'),'File visible staff';
 assert has_table_privilege('service_role','public.rgpd_fichiers_a_effacer','SELECT,INSERT,UPDATE,DELETE'),'Grants service absents';
 assert (select relrowsecurity from pg_class where oid='public.rgpd_fichiers_a_effacer'::regclass),'RLS absente';
 assert not has_function_privilege('authenticated','public.preparer_effacement_figurant(uuid,uuid)','EXECUTE'),'RPC préparation staff';
 assert not has_function_privilege('anon','public.terminer_effacement_figurant(uuid,uuid)','EXECUTE'),'RPC fin anon';
 insert into public.figurants(id,prenom,nom,email,date_naissance,code_postal,agent_email,acces_compte) values(subject,'RGPD','Fictif','rgpd@example.test','1990-01-01','75000','agent@example.test',true);
 path:=subject::text||'/fictif.png';
 insert into storage.objects(bucket_id,name) values('figurant-photos',path);
 insert into public.figurant_comptes(figurant_id,password_hash) values(subject,'fixture-non-utilisable');
 insert into public.candidatures(id,figurant_id,annonce_id,message,date_naissance) values(candidature,subject,'00000000-0000-4000-8000-00000000a000','Identité fictive','1990-01-01');
 insert into public.bookings(id,figurant_id,projet_id,date,notes) values(booking,subject,'00000000-0000-4000-8000-0000000070e0',current_date+10,'Coordonnées fictives');
 insert into public.figurant_messages(figurant_id,sender,corps,booking_id) values(subject,'staff','Message privé fictif',booking);
 insert into public.casting_roles(id,projet_id,nom) values(role_id,'00000000-0000-4000-8000-0000000070e0','RGPD fixture');
 insert into public.casting_entries(id,figurant_id,role_id,projet_id,notes,reponses) values(casting,subject,role_id,'00000000-0000-4000-8000-0000000070e0','Notes fictives','{"nom":"Fictif"}');
 set local role service_role;
 plan:=public.preparer_effacement_figurant(subject,actor);
 assert jsonb_array_length(plan->'files')=1,'Fichier oublié';
 assert (select notes is null from public.bookings where id=booking),'Notes booking conservées';
 assert (select message is null and date_naissance is null from public.candidatures where id=candidature),'Snapshot candidature conservé';
 assert (select notes is null and reponses='{}'::jsonb and not visible_partage from public.casting_entries where id=casting),'Casting non nettoyé';
 assert not exists(select 1 from public.figurant_messages where figurant_id=subject),'Messages conservés';
 perform set_config('booking.rgpd_cleanup','',true);
 set local role authenticated;
 perform set_config('booking.rgpd_cleanup','1',true);
 begin update public.figurants set email='usurpation@example.test' where id=subject; raise exception using errcode='ZX002',message='Usurpation rôle acceptée'; exception when insufficient_privilege then null; end;
 set local role service_role;
 perform set_config('booking.rgpd_cleanup','',true);
 assert (select email is null and date_naissance is null and code_postal is null and agent_email is null and not acces_compte and anonymisation_en_cours_at is not null and not anonymise from public.figurants where id=subject),'Données ou état incomplets';
 begin update public.figurants set email='revient@example.test' where id=subject; raise exception using errcode='ZX002',message='Réécriture acceptée'; exception when insufficient_privilege then null; end;
 begin insert into storage.objects(bucket_id,name) values('figurant-photos',subject::text||'/retard.png'); raise exception using errcode='ZX002',message='Upload tardif accepté'; exception when insufficient_privilege then null; end;
 begin perform public.terminer_effacement_figurant(subject,actor); raise exception using errcode='ZX002',message='Fin malgré fichier présent'; exception when check_violation then null; end;
 plan:=public.preparer_effacement_figurant(subject,actor);
 assert jsonb_array_length(plan->'files')=1,'Plan perdu lors de reprise';
 raise exception using errcode='ZX001',message='rollback fixtures';
 exception when sqlstate 'ZX001' then null; end;
end $test$;
